#!/usr/bin/env bash
# Puts Ziggy's iOS customisations (src-tauri/ios/) into the Xcode project generated by
# `tauri ios init` (src-tauri/gen/apple), then regenerates the .xcodeproj with XcodeGen.
# Idempotent: run it after every `tauri ios init`. Needs macOS + XcodeGen.
#   - app icon (single 1024 px, Xcode makes the other sizes)
#   - launch screen: Ziggy on the site's background colour, light and dark
#   - privacy manifest (no tracking, nothing collected by the app)
# Info.plist keys live in src-tauri/Info.ios.plist (merged by the Tauri CLI at build time).
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
tauri="$here/../src-tauri"
apple="$tauri/gen/apple"
src="$tauri/ios"

if [ ! -f "$apple/project.yml" ]; then
  echo "No Xcode project: run 'npx tauri ios init --ci' in apps/ziggy-app first." >&2
  exit 1
fi

assets="$apple/Assets.xcassets"
rm -rf "$assets/AppIcon.appiconset" "$assets/LaunchZiggy.imageset" "$assets/LaunchBackground.colorset"
cp -R "$src/AppIcon.appiconset" "$src/LaunchZiggy.imageset" "$src/LaunchBackground.colorset" "$assets/"
cp "$src/LaunchScreen.storyboard" "$apple/LaunchScreen.storyboard"
cp "$src/PrivacyInfo.xcprivacy" "$apple/PrivacyInfo.xcprivacy"

# The privacy manifest must be a bundle resource of the app target.
if ! grep -q 'PrivacyInfo.xcprivacy' "$apple/project.yml"; then
  awk '{ print } /^      - path: LaunchScreen.storyboard$/ { print "      - path: PrivacyInfo.xcprivacy"; print "        buildPhase: resources" }' \
    "$apple/project.yml" > "$apple/project.yml.tmp"
  mv "$apple/project.yml.tmp" "$apple/project.yml"
fi
grep -q 'PrivacyInfo.xcprivacy' "$apple/project.yml" || { echo "could not add PrivacyInfo.xcprivacy to project.yml" >&2; exit 1; }

(cd "$apple" && xcodegen generate --spec project.yml)
echo "iOS overlay applied to $apple"
